function el(tag, className, text) { const node=document.createElement(tag); if(className) node.className=className; if(text!==undefined) node.textContent=text; return node }
function button(text, className, onClick) {const node=el('button',className,text);node.type='button';node.addEventListener('click',onClick);return node}
function message(text, error=false) {return el('div',`message${error?' message--error':''}`,text)}
function escapeHtml(value) {return String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')}
function setMessage(text,error=false){state.message=error?'':text;state.error=error?text:'';const slot=document.getElementById('status');if(slot)slot.replaceChildren(text?message(text,error):'')}
function slug(value) {return String(value).normalize('NFKD').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,80)}

function loginScreen(mode='login',token=''){
  root.innerHTML=`<div class="login"><section class="login__brand"><div class="login__logo"><img src="/images/new-logo.png" alt="Vanessa Flow Yoga"></div><div class="login__welcome"><span class="login__kicker">A little space to grow</span><h1>Your studio,<br>your stories.</h1><p>Keep the words, classes, stories and retreats on your website feeling just like you.</p></div><a href="https://vanessaflowyoga.co.uk">← Back to the website</a></section><section class="login__form-wrap"><div class="login__card"><span class="eyebrow">Your website studio</span><h2>${mode==='invite'?'Set your password':mode==='recovery'?'Choose a new password':mode==='forgot'?'Reset your password':'Lovely to see you'}</h2><p class="muted">${mode==='login'?'Sign in to look after your website.':'This account is for the website admin only.'}</p><div id="status"></div><form id="auth-form">${mode==='login'||mode==='forgot'?'<label class="field"><span>Email address</span><input name="email" type="email" autocomplete="email" required></label>':''}${mode!=='forgot'?`<label class="field"><span>${mode==='login'?'Password':'New password'}</span><input name="password" type="password" autocomplete="${mode==='login'?'current-password':'new-password'}" minlength="12" required></label>`:''}<button class="btn btn--primary full" type="submit">${mode==='invite'?'Create account':mode==='recovery'?'Save new password':mode==='forgot'?'Send reset link':'Sign in'}</button></form><p><button id="auth-switch" class="btn btn--plain" type="button">${mode==='login'?'Forgot your password?':'Back to sign in'}</button></p></div></section></div>`
  document.getElementById('auth-switch').onclick=()=>loginScreen(mode==='login'?'forgot':'login')
  if(demo)document.getElementById('status').replaceChildren(message('Visual preview only. Email/password sign-in becomes active after Netlify Identity is enabled.'))
  document.getElementById('auth-form').onsubmit=async(event)=>{
    event.preventDefault();const form=event.currentTarget;const submit=form.querySelector('button[type=submit]');submit.disabled=true;setMessage('')
    try{const data=new FormData(form);if(mode==='login') await login(data.get('email'),data.get('password'))
      else if(mode==='forgot'){await requestPasswordRecovery(data.get('email'));setMessage('Check your inbox for a password reset link.');return}
      else if(mode==='invite') await acceptInvite(token,data.get('password'))
      else await updateUser({password:data.get('password')})
      state.user=await getUser();await loadMode();renderShell();openHome()
    }catch(error){setMessage(error.message||'Unable to sign in. Please try again.',true)}finally{submit.disabled=false}
  }
}

function renderShell(){
  root.innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><div class="sidebar__brand"><div class="sidebar__identity"><img src="/images/new-logo.png" alt="Vanessa Flow Yoga"><small>Website studio</small></div><button class="mobile-menu" id="menu-button" aria-label="Open menu">☰</button></div><nav id="side-nav"></nav><div class="sidebar__bottom"><div>${escapeHtml(state.user?.email||'Local preview')}</div><button id="sign-out">Sign out</button></div></aside><div class="main"><header class="topbar"><strong>Website studio <span>✳</span></strong><a href="https://vanessaflowyoga.co.uk" target="_blank" rel="noopener">View live website ↗</a></header><main class="content" id="content"></main></div></div>`
  const nav=document.getElementById('side-nav');nav.appendChild(button('Overview','',openHome));for(const section of sections)nav.appendChild(button(section.title,'',()=>openSection(section.id)))
  document.getElementById('menu-button').onclick=()=>document.getElementById('sidebar').classList.toggle('open')
  document.getElementById('sign-out').onclick=async()=>{if(!demo)await logout();state.user=null;loginScreen()}
}
function activeNav(label){document.querySelectorAll('#side-nav button').forEach(b=>b.classList.toggle('active',b.textContent===label));document.getElementById('sidebar').classList.remove('open')}
function openHome(){state.view='home';activeNav('Overview');const content=document.getElementById('content');content.innerHTML='<section class="hero"><span class="eyebrow">Your website studio</span><h1>Welcome back to the flow.</h1><p>Choose an area to update. Publish your changes directly to the website.</p></section><div class="quick-grid" id="quick-grid"></div><div class="note"><strong>Site health</strong><br><span id="health-status">Checking monitoring…</span><br><span id="credential-status">Checking content connection…</span><br><button type="button" id="health-open">Open health checks →</button></div><div class="note"><strong>Good to know</strong><br>Website timetable and prices do not change Momence bookings or checkout products. Check those separately before publishing here.</div>';const grid=document.getElementById('quick-grid');for(const section of sections){const card=button('', 'quick',()=>openSection(section.id));card.innerHTML=`<strong>${escapeHtml(section.title)}</strong><span>${escapeHtml(section.intro)}</span><em>Open section →</em>`;grid.appendChild(card)}document.getElementById('health-open').onclick=()=>openSection('health');loadHealth()}
async function loadHealth(){const slot=document.getElementById('health-status');const credentialSlot=document.getElementById('credential-status');if(demo){slot.textContent='Open Site health to preview the dashboard. Live checks appear after sign-in.';credentialSlot.textContent='GitHub connection status appears here after sign-in.';return}try{const response=await fetch('/.netlify/functions/admin-health',{credentials:'same-origin'});const data=await response.json();if(!response.ok)throw Error(data.error||'Monitoring unavailable');slot.textContent=data.status==='not-run'?'No site health check has run yet.':data.status==='stale'?'Checks are overdue. Open Site health to run them now.':data.status==='attention'?`${data.report.summary.fail} checks need attention.`:data.status==='warning'?`${data.report.summary.warn} checks need review.`:'Last site health check passed.';const credential=data.credential;const date=new Date(`${credential.expiresAt}T00:00:00Z`).toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'});credentialSlot.textContent=credential.status==='unknown'?'Action needed: set the GitHub token expiry date in the admin project.':credential.status==='missing'?'GitHub content connection is not set up yet.':credential.status==='expired'?`Action needed: GitHub content token expired on ${date}.`:credential.status==='expiring'?`Action needed: GitHub content token expires on ${date} (${credential.daysLeft} days left).`:`GitHub content token expires on ${date}.`;credentialSlot.classList.toggle('message--error',credential.status==='unknown'||credential.status==='missing'||credential.status==='expired'||credential.status==='expiring')}catch{slot.textContent='Monitoring status unavailable.';credentialSlot.textContent='GitHub connection status unavailable.'}}
function heading(title,intro){const wrap=el('div','page-head');const left=el('div');left.innerHTML=`<span class="eyebrow">Manage content</span><h1>${escapeHtml(title)}</h1><p>${escapeHtml(intro)}</p>`;wrap.appendChild(left);return wrap}
async function api(query,options){if(demo){if(options)throw Error('Local preview is read-only. Sign in on the hosted admin to save.');const url=new URLSearchParams(query);if(url.has('collection')){const posts=url.get('collection')==='posts';const r=await fetch(posts?'/content/latest-posts.json':'/content/retreat-list.json');if(!r.ok)throw Error('Could not load preview entries.');const data=await r.json();return {entries:posts?data.posts.map(p=>({name:p.title,title:p.title,published:p.published,path:`post/${p.href.split('/').pop()}.md`})):(data.retreats||[]).map(r=>({name:r.title,path:`content/retreats/${r.slug}.json`}))}}if(url.get('path')?.endsWith('.md'))throw Error('Existing blog articles open after the hosted admin is connected.');const r=await fetch('/'+url.get('path'));if(!r.ok)throw Error('Could not load local preview data.');return {path:url.get('path'),sha:null,content:await r.text()}}const url='/.netlify/functions/admin-content?'+new URLSearchParams(query);const r=await fetch(url,{credentials:'same-origin',...options});const json=await r.json();if(!r.ok)throw Error(json.error||'Unable to load content.');return json}
async function loadMode(){if(demo)return;const result=await resolveEditorMode(()=>api({mode:'1'}));state.mode=result.mode;state.modeError=result.error}
async function openSection(id){const section=sections.find(s=>s.id===id);state.view=id;activeNav(section.title);const content=document.getElementById('content');content.replaceChildren(heading(section.title,section.intro),el('div','loading','Loading…'));try{await loadMode();if(id==='media'){await openMedia(section);return}if(id==='health'){await openHealth(section);return}if(section.collection){await listEntries(section);return}const entry=await api({path:section.path});state.path=section.path;state.sha=entry.sha;state.data=JSON.parse(entry.content);renderEditor(section)}catch(error){content.appendChild(message(error.message,true))}}

function formatBytes(bytes){return bytes<1024?`${bytes} B`:bytes<1048576?`${Math.round(bytes/1024)} KB`:`${(bytes/1048576).toFixed(1)} MB`}
function mediaCard(asset){
  const card=el('details','media-card');const summary=el('summary','media-card__summary');const thumb=el('span','media-card__thumb');let dimensions=null
  if(asset.type==='image'){const image=el('img');image.src=asset.path;image.alt='';image.loading='lazy';image.onload=()=>{if(dimensions)dimensions.textContent=`${image.naturalWidth} × ${image.naturalHeight} px`};thumb.appendChild(image)}
  else thumb.appendChild(el('span','media-card__video','▶ Video'))
  const identity=el('span','media-card__identity');identity.append(el('strong','',asset.filename),el('small','',`${asset.format} · ${formatBytes(asset.bytes)} · ${asset.uses.length} ${asset.uses.length===1?'reference':'references'}`));summary.append(thumb,identity,el('span','media-card__chevron','⌄'));card.appendChild(summary)
  const body=el('div','media-card__body');dimensions=el('p','media-card__dimensions',asset.type==='video'?'Video file':'Dimensions load with the image');body.appendChild(dimensions)
  const original=el('a','media-card__original','Open original ↗');original.href=asset.path;original.target='_blank';original.rel='noopener';body.appendChild(original)
  const imageUses=asset.uses.filter(use=>use.kind==='Image'||use.kind==='Background image');const altValues=[...new Set(imageUses.map(use=>use.alt).filter(value=>value!==null))]
  body.appendChild(el('h3','','Alt text on the site'))
  if(!imageUses.length)body.appendChild(el('p','muted','No image placement with alt text was found.'))
  else if(!altValues.length)body.appendChild(el('p','media-warning','No alt text found in the indexed page placements.'))
  else for(const alt of altValues)body.appendChild(el('p','media-alt',alt===''?'Empty alt text (decorative image)':alt))
  const titles=[...new Set(asset.uses.map(use=>use.title).filter(Boolean))]
  body.appendChild(el('h3','','Image title'))
  body.appendChild(el('p','muted',titles.length?titles.join(' · '):'No separate image title is set. Page and article titles are listed below.'))
  body.appendChild(el('h3','','Used on'))
  if(!asset.uses.length)body.appendChild(el('p','muted','No reference found in the current site build. It may be unused or loaded dynamically.'))
  else {
    const list=el('ul','media-uses');for(const use of asset.uses){const item=el('li');const label=use.pageTitle||use.page;const link=el('a','',label);link.href=use.page;link.target='_blank';link.rel='noopener';item.appendChild(link);item.appendChild(el('small','',`${use.kind}${use.alt===null?'':use.alt===''?' · decorative':` · alt: ${use.alt}`}`));list.appendChild(item)}body.appendChild(list)
  }
  card.appendChild(body);return card
}
async function openMedia(section){
  const content=document.getElementById('content');const response=await fetch('/admin/media-library.json',{cache:'no-store'});if(!response.ok)throw Error('Could not load the media library.');const data=await response.json();
  content.replaceChildren(heading(section.title,section.intro));const note=el('div','note','This library reads the current site build. Alt text belongs to each page placement, so one photo may have several descriptions. This view does not edit files or page wording.');content.appendChild(note)
  const controls=el('div','media-controls');const search=el('input');search.type='search';search.placeholder='Search filename, page or alt text';search.setAttribute('aria-label','Search media');const filter=el('select');filter.setAttribute('aria-label','Filter media');for(const [value,label] of [['all','All media'],['images','Images'],['videos','Videos'],['unreferenced','No references found'],['missing-alt','Missing alt text']]){const option=el('option','',label);option.value=value;filter.appendChild(option)}controls.append(search,filter);content.appendChild(controls)
  const count=el('p','media-count');const grid=el('div','media-grid');content.append(count,grid)
  function render(){const term=search.value.trim().toLowerCase();const matches=data.assets.filter(asset=>{if(filter.value==='images'&&asset.type!=='image')return false;if(filter.value==='videos'&&asset.type!=='video')return false;if(filter.value==='unreferenced'&&asset.uses.length)return false;if(filter.value==='missing-alt'&&!asset.uses.some(use=>use.kind==='Image'&&use.alt===null))return false;return !term||[asset.path,...asset.uses.flatMap(use=>[use.pageTitle,use.page,use.alt,use.title])].some(value=>String(value||'').toLowerCase().includes(term))});count.textContent=`${matches.length} of ${data.assets.length} files`;grid.replaceChildren(...matches.map(mediaCard));if(!matches.length)grid.appendChild(el('p','muted','No media matches this search.'))}
  search.addEventListener('input',render);filter.addEventListener('change',render);render()
}

const healthLabels={availability:'Site and admin',pages:'All pages',links:'Internal and external links',security:'Security and HTTPS',seo:'Search and blog SEO',forms:'Forms configured',cookies:'Cookie blocking checks',media:'Images and videos',speed:'Server response time',mobile:'Mobile setup checks',integrations:'Instagram and Momence',github:'GitHub connection'}
async function healthApi(suffix='',options){const response=await fetch('/.netlify/functions/admin-health'+suffix,{credentials:'same-origin',...options});const data=await response.json();if(!response.ok)throw Error(data.error||'Health checks are unavailable.');return data}
function healthStatusLabel(status){return status==='fail'?'Needs attention':status==='warn'?'Check manually':status==='pass'?'Working':'Not checked'}
async function openHealth(section){
  const content=document.getElementById('content');const data=demo?{status:'not-run',report:null,categories:Object.keys(healthLabels),manualItems:[{id:'form:contact',label:'contact form delivery',url:'/contact'},{id:'form:membership',label:'membership form delivery',url:'/membership'},{id:'form:application',label:'application form delivery',url:'/work-with-us'},{id:'form:retreat-interest',label:'retreat-interest form delivery',url:'/retreats'}],settings:{recipients:['hello@charlie-harris.com','vanessa@vanessaflowyoga.co.uk'],alertCategories:Object.keys(healthLabels),manual:{}},alertsConfigured:false,credential:{status:'ok',expiresAt:'2026-10-24'}}:await healthApi()
  content.replaceChildren(heading(section.title,section.intro))
  const toolbar=el('div','health-toolbar');const run=button('Run checks now','btn btn--primary',async()=>{run.disabled=true;run.textContent='Checking the website…';feedback.textContent='Checking pages, links, images and services. This can take a moment.';try{await healthApi('?run=1',{method:'POST',headers:{'content-type':'application/json'},body:'{}'});await openHealth(section)}catch(error){feedback.textContent=error.message;run.disabled=false;run.textContent='Run checks now'}});run.disabled=demo;toolbar.appendChild(run);const checked=data.report?.checkedAt?new Date(data.report.checkedAt).toLocaleString('en-GB'):'Never';toolbar.appendChild(el('span','muted',`Last automatic check: ${checked}`));content.appendChild(toolbar)
  const feedback=el('div','health-feedback');feedback.setAttribute('role','status');content.appendChild(feedback)
  const overview=el('div',`health-overview health-overview--${data.status}`);overview.appendChild(el('strong','',data.status==='attention'?`${data.report.summary.fail} checks need attention`:data.status==='warning'?`${data.report.summary.warn} checks need review`:data.status==='healthy'?'Automatic checks passed':data.status==='stale'?'Checks are overdue':'No automatic results yet'));overview.appendChild(el('p','',data.status==='not-run'?'The daily monitor will run after deployment. You can also run it here.':'Automatic checks do not submit forms or prove legal compliance. Hands-on test records are below.'));content.appendChild(overview)
  const categories=el('div','health-categories');for(const category of data.categories){const rows=data.report?.results.filter(item=>item.category===category)||[];const fail=rows.filter(item=>item.status==='fail').length,warn=rows.filter(item=>item.status==='warn').length;const status=!rows.length?'unknown':fail?'fail':warn?'warn':'pass';const card=el('details',`health-category health-category--${status}`);const summary=el('summary');summary.append(el('span','health-dot',status==='pass'?'✓':status==='fail'?'!':status==='warn'?'?':'–'),el('strong','',healthLabels[category]||category),el('small','',!rows.length?'Not checked yet':fail?`${fail} failed`:warn?`${warn} need review`:`${rows.length} passed`));card.appendChild(summary);const list=el('div','health-results');for(const item of rows){const row=el('div',`health-result health-result--${item.status}`);row.appendChild(el('span','',healthStatusLabel(item.status)));const main=el('div');main.appendChild(el('strong','',item.name));if(item.detail)main.appendChild(el('small','',item.detail));if(item.url){const link=el('a','',item.url.startsWith('https://app.behold.so/')?'Check Behold account ↗':'Open ↗');link.href=item.url;link.target='_blank';link.rel='noopener';main.appendChild(link)}row.appendChild(main);list.appendChild(row)}if(!rows.length)list.appendChild(el('p','muted','No result has been recorded yet.'));card.appendChild(list);categories.appendChild(card)}content.appendChild(categories)
  content.appendChild(el('div','note','Cookie, speed and mobile checks run with the site audit. They cover consent gates, server response and responsive setup. They do not certify GDPR compliance, measure real visitor speed or catch every visual layout issue. We review those separately when the site changes.'))
  const manual=el('section','panel health-manual');manual.appendChild(el('h2','','Form delivery tests'));manual.appendChild(el('p','muted','Automatic checks confirm that forms exist, but cannot prove an enquiry reached your inbox. Send a test entry, check its arrival, then record the result here.'))
  for(const item of data.manualItems){const record=data.settings.manual?.[item.id];const row=el('div','manual-row');const left=el('div');left.appendChild(el('strong','',item.label));left.appendChild(el('small','',record?`${record.status==='pass'?'✓ Passed':'! Failed'} · last tested ${new Date(record.checkedAt).toLocaleString('en-GB')}`:'Not tested yet'));row.appendChild(left);const actions=el('div','manual-actions');const open=el('a','btn btn--soft',item.id.startsWith('form:')?'Open form ↗':'Open page ↗');open.href='https://vanessaflowyoga.co.uk'+item.url;open.target='_blank';open.rel='noopener';actions.appendChild(open);for(const [status,label] of [['pass',item.id.startsWith('form:')?'I confirmed receipt':'I checked — passed'],['fail','Mark failed']]){const control=button(label,status==='pass'?'btn btn--soft':'btn btn--plain',async()=>{if(demo)return;control.disabled=true;try{await healthApi('?manual='+encodeURIComponent(item.id),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({status})});await openHealth(section)}catch(error){feedback.textContent=error.message;control.disabled=false}});control.disabled=demo;actions.appendChild(control)}row.appendChild(actions);manual.appendChild(row)}content.appendChild(manual)
  const alerts=el('section','panel health-alerts');alerts.appendChild(el('h2','','Email me if…'));alerts.appendChild(el('p','muted','Choose who receives an email when a selected check is red. Addresses are stored privately with the admin project. Weekly status emails go out on Monday mornings. Essential availability and token checks run hourly; the full site audit runs daily. New failures and recoveries trigger alerts without repeating unchanged issues. Token warnings escalate at 14 days, 7 days, 1 day and expiry.'))
  if(!data.alertsConfigured)alerts.appendChild(el('div','message message--error','Email sending is not active yet. Add RESEND_API_KEY and HEALTH_ALERT_FROM to this admin Netlify project, then redeploy and test delivery.'))
  const label=el('label','field');label.appendChild(el('span','','Notification email addresses (one per line)'));const emails=el('textarea');emails.value=data.settings.recipients.join('\n');emails.rows=3;label.appendChild(emails);alerts.appendChild(label)
  const choices=el('div','alert-choices');for(const category of data.categories){const option=el('label','alert-choice');const input=el('input');input.type='checkbox';input.value=category;input.checked=data.settings.alertCategories.includes(category);option.append(input,el('span','',healthLabels[category]||category));choices.appendChild(option)}alerts.appendChild(choices)
  const save=button('Save email choices','btn btn--primary',async()=>{if(demo)return;save.disabled=true;try{const recipients=emails.value.split(/[\n,;]+/).map(value=>value.trim()).filter(Boolean);const alertCategories=[...choices.querySelectorAll('input:checked')].map(input=>input.value);await healthApi('',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({recipients,alertCategories})});await openHealth(section)}catch(error){feedback.textContent=error.message;save.disabled=false}});save.disabled=demo;alerts.appendChild(save);
  const testEmail=button('Send test email','btn btn--soft',async()=>{testEmail.disabled=true;try{const result=await healthApi('?test-email=1',{method:'POST',headers:{'content-type':'application/json'},body:'{}'});feedback.textContent=result.message}catch(error){feedback.textContent=error.message}finally{testEmail.disabled=demo||!data.alertsConfigured}});testEmail.disabled=demo||!data.alertsConfigured;alerts.appendChild(testEmail);
  const weeklyEmail=button('Send weekly report now','btn btn--soft',async()=>{weeklyEmail.disabled=true;try{const result=await healthApi('?weekly-email=1',{method:'POST',headers:{'content-type':'application/json'},body:'{}'});feedback.textContent=result.message}catch(error){feedback.textContent=error.message}finally{weeklyEmail.disabled=demo||!data.alertsConfigured}});weeklyEmail.disabled=demo||!data.alertsConfigured;alerts.appendChild(weeklyEmail);
  const delivery=data.delivery||data.report?.notification;if(delivery)alerts.appendChild(el('p','muted',`Last email attempt: ${delivery.status}${delivery.at?' · '+new Date(delivery.at).toLocaleString('en-GB'):''}${delivery.detail?' — '+delivery.detail:''}.`));
  alerts.appendChild(el('p','muted',`Last weekly report accepted: ${data.lastWeeklySentAt?new Date(data.lastWeeklySentAt).toLocaleString('en-GB'):'Not sent yet'}.`));
  if(data.essentialCheckedAt)alerts.appendChild(el('p','muted',`Latest essential check: ${new Date(data.essentialCheckedAt).toLocaleString('en-GB')}.`));
  content.appendChild(alerts)
  const expiry=new Date(`${data.credential.expiresAt}T00:00:00Z`).toLocaleDateString('en-GB');content.appendChild(el('div','note',data.credential.status==='unknown'?'GitHub publishing token expiry is not configured. Set its actual expiry date in the admin project.':`GitHub publishing token: ${data.credential.status==='expired'?'expired':data.credential.status==='expiring'?'renew soon':'expires'} ${expiry}.`))
}

function scalar(container,obj,spec){const label=el('label','field');label.appendChild(el('span','',spec.label));let input
  if(spec.type==='textarea')input=el('textarea');else if(spec.type==='select'){input=el('select');for(const option of spec.options){const choice=el('option','',option);choice.value=option;input.appendChild(choice)}}else{input=el('input');input.type=spec.type==='checkbox'?'checkbox':spec.type==='number'?'number':spec.type==='date'?'date':spec.type==='time'?'time':'text'}
  if(spec.max)input.maxLength=spec.max;if(spec.type==='checkbox'){input.checked=!!obj[spec.key];input.onchange=()=>obj[spec.key]=input.checked}else{input.value=obj[spec.key]??'';input.oninput=()=>{if(spec.key==='amount'){changePrice(obj,Number(input.value));const panel=container.closest('.subpanel');const confirmation=panel?.querySelector('[data-price-confirmation]');if(confirmation){confirmation.checked=false;panel.querySelector('[data-price-confirmation-label]').textContent=`I have checked that £${obj.amount} matches the price in Momence.`}}else obj[spec.key]=spec.type==='number'?Number(input.value):input.value;if(spec.key==='booking_url'){const id=checkout.productId(input.value);if(id){obj.product_id=id;const panel=container.closest('.subpanel');const productInput=panel?.querySelector('[data-product-id]');if(productInput){productInput.value=id;const count=productInput.parentElement.querySelector('.count');if(count)count.textContent=`${id.length}/30`}}}if(spec.max)counter.textContent=`${input.value.length}/${spec.max}`}}
  if(spec.key==='product_id'){input.readOnly=true;input.dataset.productId='true';label.appendChild(el('small','','Filled automatically from the Momence checkout link.'))}label.appendChild(input);const counter=spec.max?el('small','count',`${String(obj[spec.key]??'').length}/${spec.max}`):null;if(counter)label.appendChild(counter);container.appendChild(label)
  if(spec.type==='image'){const upload=el('input');upload.type='file';upload.accept='image/jpeg,image/png,image/webp';upload.disabled=demo;const hint=el('small','',demo?'Photo upload is available after sign-in.':'Upload a JPG, PNG or WebP under 2 MB.');label.append(upload,hint);upload.onchange=async()=>{const file=upload.files?.[0];if(!file)return;try{if(file.size>2000000)throw Error('Choose a photo under 2 MB.');hint.textContent='Uploading photo…';const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('Could not read photo.'));reader.readAsDataURL(file)});const name=`${Date.now()}-${slug(file.name.replace(/\.[^.]+$/,''))}.${file.name.split('.').pop().toLowerCase()}`;const saved=await api({upload:'1'},{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({folder:spec.options,filename:name,base64})});obj[spec.key]=saved.path;input.value=saved.path;hint.textContent='Photo uploaded. Save this page to use it.'}catch(error){hint.textContent=error.message;upload.value=''}}}
  if(spec.type==='video'){input.placeholder='Upload an MP4 or paste its HTTPS link';const upload=el('input');upload.type='file';upload.accept='video/mp4';upload.disabled=demo;const hint=el('small','',demo?'Video upload is available after sign-in.':'Upload an MP4 under 4 MB, or paste an HTTPS MP4 URL. Use the poster photo while the video loads.');label.append(upload,hint);upload.onchange=async()=>{const file=upload.files?.[0];if(!file)return;upload.disabled=true;try{if(file.size>4000000)throw Error('Use an MP4 under 4 MB or paste a hosted MP4 link.');hint.textContent='Uploading video…';const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('Could not read video.'));reader.readAsDataURL(file)});const filename=`${Date.now()}-${slug(file.name.replace(/\.[^.]+$/,''))}.mp4`;const saved=await api({upload:'1'},{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({folder:'videos/retreats',filename,base64})});obj[spec.key]=saved.path;input.value=saved.path;state.reviewed=null;hint.textContent='Video uploaded. Publish this page to use it. Publish changes directly.'}catch(error){hint.textContent=error.message;upload.value=''}finally{upload.disabled=demo}}}

}
function fields(container,obj,schema){const grid=el('div','form-grid');for(const spec of schema){const wrapper=el('div',spec.type==='textarea'?'wide':'');scalar(wrapper,obj,spec);grid.appendChild(wrapper)}container.appendChild(grid)}
function listEditor(container,items,schema,options={}){const holder=el('div');function redraw(){holder.replaceChildren();items.forEach((item,index)=>{const panel=el('div','subpanel');const head=el('div','subpanel__head');head.appendChild(el('h3','',options.title?options.title(item,index):`Item ${index+1}`));if(!options.fixed)head.appendChild(button('Remove','',()=>{items.splice(index,1);redraw()}));panel.appendChild(head);if(typeof item==='string'){const label=el('label','field');label.appendChild(el('span','','Description'));const input=el('input');input.maxLength=90;input.value=item;input.oninput=()=>items[index]=input.value;label.appendChild(input);panel.appendChild(label)}else fields(panel,item,schema);if(options.priceConfirmation){const label=el('label','price-confirmation');const input=el('input');input.type='checkbox';input.dataset.priceConfirmation='true';input.checked=item.amount===item.momence_confirmed_amount;input.onchange=()=>confirmPrice(item,input.checked);const text=el('span','',`I have checked that £${item.amount} matches the price in Momence.`);text.dataset.priceConfirmationLabel='true';label.append(input,text);panel.appendChild(label)}if(options.child){const sub=el('div');sub.appendChild(el('h3','','Classes'));listEditor(sub,item.classes,classFields,{title:(entry)=>`${entry.time||'New time'} · ${entry.name||'New class'}`,empty:()=>({time:'09:00',name:'',style:'flow'})});panel.appendChild(sub)}holder.appendChild(panel)});if(!options.fixed)holder.appendChild(button('+ Add another','btn btn--soft',()=>{items.push(options.empty());redraw()}))}redraw();container.appendChild(holder)}
async function refreshPopupStatus() {
  const slot=document.getElementById('popup-live-status');if(!slot)return;
  slot.textContent='Checking the public website…';
  try {
    const result=demo?{status:popup.status(state.data),data:state.data}:await api({'popup-live':'1'});
    if(!slot.isConnected)return;
    const badge=el('strong','',demo?'Local preview':result.status.label);
    badge.style.cssText='display:inline-block;padding:5px 14px;border-radius:99px;color:white;background:'+(result.status.label==='Live'?'#287153':'#49545a');
    slot.replaceChildren(badge,el('p','',result.status.detail),el('small','',demo?'This is not a live-site check.':'Checked against the public website just now. Publishing may take a minute.'));
  }catch(error){slot.replaceChildren(el('strong','','Status unavailable'),el('p','',error.message))}
}
function popupStatusPanel(content) {
  const panel=el('section','panel');panel.appendChild(el('h2','','Public website status'));
  const slot=el('div');slot.id='popup-live-status';slot.setAttribute('aria-live','polite');panel.appendChild(slot);
  panel.appendChild(button('Refresh live status','btn btn--soft',refreshPopupStatus));
  const draft=el('p');draft.id='popup-draft-status';draft.textContent='Editor settings: '+popup.status(state.data).label+'. Publish to apply changes. Publish changes directly.';panel.appendChild(draft);
  content.appendChild(panel);refreshPopupStatus();
}
function renderEditor(section,post=false){state.reviewed=null;const content=document.getElementById('content');content.replaceChildren(heading(section.title,section.intro));if(section.id==='popup')popupStatusPanel(content);const panel=el('section','panel');panel.appendChild(el('h2','',post?'Article details':section.title));if(post){panel.appendChild(el('p','muted','Search fields are optional. Existing posts keep their current headline and summary until you add separate search wording. The article web address stays the same.'));fields(panel,state.data,postFields);const body=el('label','field');body.appendChild(el('span','','Article text'));const textarea=el('textarea','markdown');textarea.value=state.postBody;textarea.oninput=()=>state.postBody=textarea.value;body.appendChild(textarea);body.appendChild(el('small','','Use ## for section headings.'));panel.appendChild(body)}else if(section.legal){fields(panel,state.data,[field('updated','Last updated',0,'date')]);listEditor(panel,state.data.sections,legalFields,{title:item=>item.heading||'New section',empty:()=>({id:'section-'+Date.now(),heading:'',body:''})})}else if(section.fields)fields(panel,state.data,section.fields);else if(section.id==='latest')listEditor(panel,state.data.tiles,cardFields,{fixed:true,title:(item,index)=>`Card ${index+1} · ${item.headline||'Untitled'}`});else if(section.id==='timetable')listEditor(panel,state.data.days,[],{fixed:true,title:item=>item.day,child:true});else if(section.id==='prices')listEditor(panel,state.data.plans,planFields,{fixed:true,priceConfirmation:true,title:item=>item.label});else if(section.id==='retreat-entry'){fields(panel,state.data,retreatFields);for(const key of ['experiences','inclusions']){panel.appendChild(el('h2','',key==='experiences'?'What guests will do':'What is included'));listEditor(panel,state.data[key],[],{title:(item,index)=>String(item||`Item ${index+1}`),empty:()=>''})}}content.appendChild(panel)
  if(section.id==='retreats-general')content.appendChild(el('div','note','Paste the complete Momence lead form embed for Vanessa Flow Yoga. The form loads after functional cookie consent. Video uploads are saved immediately; Preview and Publish apply the video to this page.'))
  if(section.id==='popup'){const update=()=>{const status=popup.status(state.data);document.getElementById('popup-draft-status').textContent='Unsaved editor settings: '+status.label+'. '+status.detail+' Publish to apply. Publish changes directly.'};content.addEventListener('input',update);content.addEventListener('change',update)}
  if(section.id==='prices')content.appendChild(el('div','note','Before saving: update the matching Momence products. The website build will reject a price that does not match the confirmed Momence amount.'))
  const actions=el('div','editor-actions');const access=el('small');const group=el('div','action-buttons');const save=button(state.mode==='review'?'Save to review':'Publish changes','btn btn--primary',()=>saveEntry(section,post));const retry=button('Retry connection','btn btn--soft',async()=>{retry.disabled=true;await loadMode();updateAccess();retry.disabled=false});const updateAccess=()=>{access.textContent=state.modeError|| (state.mode==='live'?'Publish your changes directly to the live site.':state.mode==='review'?'Save to the review branch. The live website will not change.':demo?'Local demonstration. Sign in on the hosted admin to publish.':'Publishing is not enabled on this admin.');save.textContent=state.mode==='review'?'Save to review':'Publish changes';save.disabled=state.mode==='readonly';retry.hidden=demo||state.mode!=='readonly';retry.style.display=retry.hidden?'none':''};updateAccess();group.append(save,retry);actions.append(access,group);content.appendChild(actions);const status=el('div');status.id='status';status.setAttribute('role','status');actions.appendChild(status);save.id='publish-changes'
}
async function saveEntry(section,post){const save=document.getElementById('publish-changes');if(save?.disabled)return;const label=save?.textContent;if(save){save.disabled=true;save.textContent='Publishing…'}setMessage('Publishing…');try{if(section.legal && legal.validate(state.data))throw Error(legal.validate(state.data));if(section.id==='prices')preparePrices(state.data.plans);if(section.id==='latest'&&state.data.tiles.filter(t=>t.size==='big').length!==1)throw Error('Exactly one latest card must be the big card.');if(section.id==='timetable'&&state.data.days.some(d=>d.classes.some((c,i)=>i&&c.time<d.classes[i-1].time)))throw Error('Keep classes in time order within each day.');if(section.id==='retreat-entry'&&state.data.go_live>state.data.end_date)throw Error('The last retreat day must be after its first day.');const path=state.path||`${post?'post':'content/retreats'}/${slug(state.data.title)}.${post?'md':'json'}`;if(!path||path.endsWith('/.md')||path.endsWith('/.json'))throw Error('Enter a title before publishing.');const text=post?`---\n${YAML.stringify(state.data)}---\n\n${state.postBody.trim()}\n`:JSON.stringify(state.data,null,2)+'\n';const result=await api({path},{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({path,sha:state.sha,content:text})});state.path=path;state.sha=result.sha;state.reviewed=null;setMessage(result.message||'Published.');if(section.id==='popup')refreshPopupStatus()}catch(error){setMessage(error.message,true)}finally{if(save?.isConnected){save.disabled=false;save.textContent=label}}}
async function listEntries(section){const content=document.getElementById('content');content.replaceChildren(heading(section.title,section.intro));const add=button(section.id==='posts'?'+ New blog post':'+ New retreat','btn btn--primary',()=>newEntry(section));content.querySelector('.page-head').appendChild(add);const list=el('div','entry-list');content.appendChild(list);const result=await api({collection:section.collection});for(const entry of result.entries){const name=entry.title||entry.name.replace(/\.(md|json)$/,'').replaceAll('-',' ');const date=section.id==='posts'?(entry.published?new Date(`${entry.published}T12:00:00Z`).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'Europe/London'}):'No publication date'):'';list.appendChild(button(`${date?date+' · ':''}${name}  →`,'entry',()=>openEntry(section,entry.path)))}if(!result.entries.length)list.appendChild(el('p','muted','No entries yet.'))}
function newEntry(section){state.path=null;state.sha=null;if(section.id==='posts'){state.data={title:'',description:'',category:'Wellbeing',published:new Date().toISOString().slice(0,10),readTime:'3 min read'};state.postBody='';renderEditor({id:'post-entry',title:'New blog post',intro:'Write your article, then save it to add it to the site.'},true)}else{state.data={schema_version:'1.0',title:'',published:false,sold_out:false,go_live:'',end_date:'',hide_after:'',eyebrow:'Your next retreat',subtitle:'',location:'',date_label:'',price_label:'',hero_image:'',hero_alt:'',overview_heading:'',overview:'',experiences:[],inclusions:[],booking_url:'',booking_cta:'Explore this retreat'};renderEditor({id:'retreat-entry',title:'New retreat',intro:'Add the story, dates and booking details. Turn on featured when ready.'})}}
async function openEntry(section,path){const content=document.getElementById('content');content.replaceChildren(heading(section.title,section.intro),el('div','loading','Loading entry…'));try{const entry=await api({path});state.path=path;state.sha=entry.sha;if(section.id==='posts'){const match=/^---\r?\n([\s\S]*?)\r?\n---\r?\n([\s\S]*)$/.exec(entry.content);if(!match)throw Error('Could not read the article details.');state.data=YAML.parse(match[1]);state.postBody=match[2];renderEditor({id:'post-entry',title:state.data.title,intro:'Edit this article. The web address stays the same.'},true)}else{state.data=JSON.parse(entry.content);renderEditor({id:'retreat-entry',title:state.data.title,intro:'Edit this retreat page and its showing dates.'})}}catch(error){content.appendChild(message(error.message,true))}}

async function boot(){if(demo){if(new URLSearchParams(location.search).has('login-preview')){loginScreen();return}state.user={email:'Local preview'};renderShell();openHome();return}try{const callback=await handleAuthCallback();if(callback?.type==='invite'){loginScreen('invite',callback.token);return}if(callback?.type==='recovery'){loginScreen('recovery');return}state.user=await getUser();if(state.user){await loadMode();renderShell();openHome()}else loginScreen()}catch(error){loginScreen();setMessage(error.message||'The admin login is not available yet.',true)}}
boot()
